local function lower(s) return type(s) == "string" and s:lower() or "" end

Data.BY_KEY, Data.BY_INST = {}, {}
local byEnc, byNpc, byName = {}, {}, {}
for _, d in ipairs(Data.LIST) do
    Data.BY_KEY[d.key] = d
    Data.BY_INST[d.inst] = Data.BY_INST[d.inst] or {}
    table.insert(Data.BY_INST[d.inst], d)
    local required = 0
    for _, b in ipairs(d.bosses) do
        b.wing = d
        if b.final then d.final = b end
        if not b.opt then required = required + 1 end
        for _, id in ipairs(b.enc or {}) do byEnc[id] = b end
        if b.npc then byNpc[b.npc] = byNpc[b.npc] or {}; table.insert(byNpc[b.npc], b) end
        for _, n in ipairs({ b.n, b.de }) do
            local k = d.inst .. ":" .. lower(n)
            byName[k] = byName[k] or {}
            table.insert(byName[k], b)
        end
    end
    -- plausible minimum for a run: one minute per boss, at least two minutes
    d.min = math.max(120, 60 * required)
end

-- the boss of a kill in an instance (by encounter ID, NPC ID or name), or nil
function Data.Boss(inst, encounterID, name, npcID)
    if ns.Num(encounterID) and byEnc[encounterID] and byEnc[encounterID].wing.inst == inst then return byEnc[encounterID] end
    if ns.Num(npcID) then
        for _, b in ipairs(byNpc[npcID] or {}) do if b.wing.inst == inst then return b end end
    end
    local list = byName[tostring(inst) .. ":" .. lower(name)]
    return list and list[1] or nil
end

-- a split (record) is the end boss of the wing: by its canonical name
function Data.IsFinal(key, split)
    local d = Data.BY_KEY[key]
    if not d or not d.final or type(split) ~= "table" then return false end
    return split.b == d.final.n
end

-- every split of a record is a boss of its wing
function Data.InWing(key, split)
    local d = Data.BY_KEY[key]
    if not d or type(split) ~= "table" then return false end
    for _, b in ipairs(d.bosses) do if b.n == split.b then return true end end
    return false
end

function Data.Name(key)
    local d = Data.BY_KEY[key]
    return d and d.name or tostring(key or "?")
end

-- instance name for an instance ID (wings: without the wing)
function Data.InstanceName(inst)
    local wings = Data.BY_INST[inst]
    if not wings then return nil end
    if #wings == 1 then return wings[1].name end
    return (wings[1].name:gsub(" – .*$", ""))
end

function Data.MinTime(key)
    local d = Data.BY_KEY[key]
    return d and d.min or 180
end

-- the boss name shown to this client (German client: German name if known)
function Data.BossName(name)
    if GetLocale and GetLocale() == "deDE" then
        for _, d in ipairs(Data.LIST) do
            for _, b in ipairs(d.bosses) do if b.n == name then return b.de or b.n end end
        end
    end
    return name
end

-- NPC ID from a creature GUID ("Creature-0-…-<npcID>-<spawn>")
function Data.NpcFromGuid(guid)
    if type(guid) ~= "string" or ns.IsSecret(guid) then return nil end
    local kind, id = guid:match("^(%a+)%-.-%-.-%-.-%-.-%-(%d+)%-")
    if kind ~= "Creature" and kind ~= "Vehicle" then return nil end
    return tonumber(id)
end
